"最大参考视频数量": "Макс. референсных видео",
"最大参考音频数量": "Макс. референсных аудио",
"约束每个生成组(generation group)的总时长与参考素材数量上限。这些数值需要与所选视频生成模型的能力对应(Seedance 2.0 系列:组时长 ≤15s、参考图 ≤9、参考视频 ≤3、参考音频 ≤3;Seedance 2.5:组时长 ≤30s、参考图 ≤30、参考视频 ≤10、参考音频 ≤10),如果不清楚建议不要修改。": "Ограничивает общую длительность и количество референсных материалов каждой группы генерации. Эти значения должны соответствовать возможностям выбранной модели генерации видео (серия Seedance 2.0: длительность группы ≤15с, изображения ≤9, видео ≤3, аудио ≤3; Seedance 2.5: длительность ≤30с, изображения ≤30, видео ≤10, аудио ≤10). Если не уверены — не меняйте.",
"选择 Seedance 2.0 时自动关闭「白模」,其他模型默认开启;可在下一步「输出设置」再手动调整。": "При выборе Seedance 2.0 «Whitebox» отключается автоматически; для других моделей по умолчанию включено. Можно изменить вручную на следующем шаге «Настройки вывода».",
"⚠ 生成模型设置里当前生效的视频模型是 {model}(对应 {family} 口径),与此处所选 {preset} 不同。不影响下一步,但建议两边保持一致,否则分镜组上限会与实际生成模型的能力不符": "⚠ В настройках моделей генерации сейчас действует видеомодель {model} (соответствует пресету {family}), что отличается от выбранного здесь {preset}. Продолжить можно, но лучше привести их в соответствие, иначе лимиты группы кадров не будут отвечать реальным возможностям модели",
"手动值": "Ручные значения",
"最大分镜组时长需为 4-30 的数值": "Макс. длительность группы должна быть числом от 4 до 30",
"最大参考图数量需为 0-30 的整数": "Макс. референсных изображений — целое число от 0 до 30",
