"构想与风格保存在项目的 brief.md,注入该项目每个 Agent 的系统提示词,作为最高创作前提;画面风格约束全部画面视觉产出。保存后对之后派发的任务生效;全部清空保存则移除该设定。叙事节奏改在「视频节奏」设置中配置": "Концепция и стиль сохраняются в brief.md проекта и внедряются в системный промпт каждого агента как главная творческая установка; визуальный стиль ограничивает весь визуальный вывод. Действует для задач, отправленных после сохранения; сохранение с пустыми полями удаляет настройку. Ритм повествования теперь настраивается в «Ритм видео»",
