",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", прикрепляются к сообщению при каждом пробуждении Продюсера автозапуском, поэтому не теряются даже после переоткрытия сессии; подходят для долгосрочных ограничений, лучше формулировать условно (напр. 「пока не завершены все сценарии ep01-ep10, не выдавать наряды на проработку сеттинга」); оставьте пустым, чтобы ничего не прикреплять",
