"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Время простоя: проверка выполняется с этим интервалом; сообщение проверки статуса отправляется только при простое конвейера (нет выполняющихся задач и пунктов, ожидающих подтверждения), по умолчанию 5 минут. Порог: если использование сессии в 5-часовом окне активного движка Продюсера (claude/codex) достигает этого значения, в этот раз сообщение не отправляется; если использование прочитать не удаётся — отправка разрешается. Обе настройки глобальные и действуют на все проекты (переключатель — кнопка 🤖 в панели запусков, независимо для каждого проекта)",
