"MiniMax 视频生成 API(MiniMax-H3,音画同生,支持首尾帧/多参考图/参考音视频);分辨率仅 768P/2K 两档:「输出设置」的 360p/480p/720p 自动映射 768P,1080p/4k 映射 2K;时长 4-15 整数秒;Key 在": "API генерации видео MiniMax (MiniMax-H3; одновременная генерация звука и видео; первый/последний кадр, несколько референс-изображений, референс-аудио/видео); только два уровня разрешения, 768P/2K: 360p/480p/720p из настроек вывода отображаются в 768P, 1080p/4k — в 2K; длительность 4–15 целых секунд; Key создаётся в",
"MiniMax 音乐生成 API(Music 系列);取消「强制纯音乐」时按 prompt 自动写词演唱;输出仅 .mp3/.wav;Key 在": "API генерации музыки MiniMax (серия Music); если “только инструментал” выключен, текст пишется автоматически по prompt и исполняется; вывод только .mp3/.wav; Key создаётся в",
