"默认关。开启后控制台每个 Agent 面板显示「SOUL.md」按钮,可查看该 Agent 的身份原文;关闭时若正在看 SOUL.md 原文会自动退回对话。全局设置,保存后立即生效,不影响任何 Agent 的运行。": "По умолчанию выключено. При включении на каждой панели Agent в консоли появляется кнопка «SOUL.md» для просмотра исходного текста личности этого Agent; при выключении во время просмотра SOUL.md происходит возврат к диалогу. Глобальная настройка, действует сразу после сохранения и не влияет на запуски Agent.",
"Issue 反馈": "Обратная связь через issue",
"诊断数据:Issue 反馈(Agent 发现宿主代码问题时整理成 GitHub issue)": "Диагностические данные: обратная связь через issue (агенты оформляют issue для GitHub при обнаружении проблемы в коде хоста)",
"默认开。Agent 运行中确认问题属于宿主代码缺陷、或需要宿主新增功能时,自动整理成 issue 列在下方,点「在浏览器中提交」即打开预填好的 GitHub 页面由你确认提交。正文只写机制,宿主已脱敏(路径、项目名、密钥),不含剧情、提示词与项目内容": "По умолчанию включено. Если агент во время работы подтверждает, что проблема является дефектом кода хоста или что хосту нужна новая функция, она автоматически оформляется как issue и появляется в списке ниже; «Отправить в браузере» открывает заранее заполненную страницу GitHub для подтверждения. Текст описывает только механизмы и уже очищен хостом (пути, названия проектов, ключи); сюжет, промпты и содержимое проекта не включаются",
