"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "API генерации изображений Fal (асинхронная очередь queue.fal.run с эндпоинтами Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image и др.); ID модели — префикс семейства: без референсов используется эндпоинт текст-в-изображение, с референсами автоматически выбирается эндпоинт редактирования; «Свой…» принимает и полный ID эндпоинта; размер / лимит референсов / seed сопоставляются по модели; ключ общий с вкладкой Видео → Fal (достаточно заполнить в одном месте), создаётся на",
