"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (хостинг Fal; первый/последний кадр, 3–15 с, нативное аудио, референсы не поддерживаются)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (хостинг Fal; первый/последний кадр, 3–15 с, нативное аудио, референсы не поддерживаются)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "API генерации видео Fal (асинхронная очередь queue.fal.run с эндпоинтами Seedance 2.0/2.5, MiniMax H3, Kling 3.0, Wan 3.0 и др.); ID модели — префикс семейства, сегмент задачи text-to-video / image-to-video / reference-to-video добавляется автоматически по входным данным, либо выберите «Свой…» и укажите полный ID эндпоинта; ограничения по разрешению/длительности/референсам зависят от выбранной модели (те же правила, что и у официальных каналов); создайте Key в",
"fal.ai 控制台「API Keys」": "панели fal.ai «API Keys»",
