"不衔接(文生视频:每段仅按提示词独立生成,不带参考图与尾帧)": "Без стыковки (текст в видео: каждый клип генерируется только по промпту, без референсов и последнего кадра)",
"不衔接:每段仅按提示词文生视频,参考图与尾帧都不提交,段与段之间画面不连续": "Без стыковки: каждый клип — текст в видео только по промпту; ни референсы, ни последний кадр не отправляются, клипы визуально не стыкуются",
"导演模式(MiniMax H3 Max Director:实时连续生成,WebRTC 直推,提示词随时改)": "Режим режиссёра (MiniMax H3 Max Director: непрерывная генерация в реальном времени, WebRTC, промпт можно менять в любой момент)",
"记忆段数": "Память (сегментов)",
"导演模式:保留最近多少段提示词作为上下文(1–50,默认 12)": "Режим режиссёра: сколько последних промптов сегментов хранить как контекст (1–50, по умолчанию 12)",
"MiniMax H3 Max Director(导演模式专用,实时 WebRTC)": "MiniMax H3 Max Director (только режим режиссёра, WebRTC в реальном времени)",
"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "Режим режиссёра тарифицируется посекундно (минимум 60 с); сессия по умолчанию не дольше 2 минут (дольше — по запросу к fal); закрытие страницы завершает её",
"导演模式:fal 侧按约 10 秒一块连续生成,单段时长/待播上限/最多段数不适用": "Режим режиссёра: fal генерирует непрерывно блоками ~10 с; длина клипа / лимит непросмотренного / макс. клипов не применяются",
"导演模式:MiniMax H3 Max Director 实时连续生成,视频经 WebRTC 直推本页,自带前文记忆不需尾帧衔接;参考图只取第 1 张作首帧;分辨率 480p/768p": "Режим режиссёра: MiniMax H3 Max Director генерирует непрерывно в реальном времени, видео приходит на эту страницу по WebRTC, встроенная память заменяет стыковку по последнему кадру; первым кадром служит только референс №1; разрешение 480p/768p",
