"⏭ 最新": "⏭ Последний",
"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Показ: готовые клипы идут по порядку; пока следующего нет, повторяется последний, а новый добавляется после текущего без прерывания. Генерация обычно медленнее показа, поэтому повторы — норма; длинные клипы уменьшают их долю. При достижении лимита ожидающих клипов (по умолчанию 3, настраивается в «Дополнительно») генерация приостанавливается и возобновляется после показа одного. После остановки все клипы идут по кругу.",
