// 分镜剪辑·插黑 / 定格(2026-09-17)
"插黑 / 定格": "Чёрное / стоп-кадр",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Удаляет отмеченные отрезки и склеивает остальное по порядку в новую версию группы (длительность сокращается; при финализации внешняя звуковая дорожка и субтитры пересинхронизируются по карте времени)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场处方(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Управление ритмом: вставить «стоп-кадр предыдущего кадра + чёрное» в позиции воспроизведения и собрать новую версию, либо поставить на границу в начале / конце группы как рецепт межгруппового перехода (отправка записывает его в shot_list; кадры вставляются при финализации). Серия удлиняется на вставку; внешний звук и субтитры сдвигаются по той же карте времени; звук под чёрным можно тянуть, затухать или глушить",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Монтаж планов, четыре модуля: ① Удалить — убрать отмеченные отрезки, остальное станет новой версией; ② Заменить — заменить вырезанные отрезки теми же отрезками другой версии; ③ Чёрное / стоп-кадр — вставить стоп-кадр + чёрное в позиции воспроизведения или на границе группы для управления ритмом; ④ Отправить монтажёру — отправить указание агенту-монтажёру, результат регистрируется как новая версия",
