"高斯模糊与原片按强度混合,压掉高频细节而不糊轮廓(回忆/梦境段的柔焦感);半径随画面高度等比缩放": "Смешивает гауссово размытие с оригиналом по силе, убирая мелкие детали без размытия контуров (мягкий фокус для флешбэков / снов); радиус масштабируется по высоте кадра",
