"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式": "Расширенные настройки агентов: параллелизм fan-out-агентов, тайм-ауты выполнения / отсутствия вывода, лимит памяти диалога между ходами, лимит автоматических повторов, время ожидания подтверждения повтора, глубина размышления, самопроверка whitebox, режим отладки",
"白模自检": "Самопроверка whitebox",
"显示 SOUL.md 等开发者入口": "Показывать входы для разработчиков, например SOUL.md",
"白模调度编译后出静帧自检取景": "После компиляции whitebox рендерить стоп-кадры для самопроверки кадрирования",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "По умолчанию включено: каждый раз, когда агент постановки whitebox создаёт или изменяет whitebox раскадровки и компиляция проходит, он запускает команду хоста render_whitebox.py --stills для групп, изменённых в этом наряде. Рендер идёт без интерфейса: для каждого кадра — виды с камеры в начале / середине / конце (и в другие ключевые моменты) плюс один пространственный вид, собранные в один контактный лист на группу (в папке whitebox/stills эпизода внутри directing проекта). Агент читает лист и проверяет, что объект в кадре, его не закрывают стены или реквизит, вид спереди / со спины соответствует постановке и крупность подходит; проблемы он исправляет сам или открывает отложенный вопрос, прежде чем передать вам на просмотр и подпись на странице предпросмотра. Рендер полностью локальный: генеративные модели не вызываются, расходов нет, camera.mp4 не экспортируется (экспорт по-прежнему требует подписи H3W); на группу уходит около десяти дополнительных секунд и токены одного чтения изображения. Если снять флажок, выполняются только числовые самопроверки и проверки хоста, без стоп-кадров. Глобальная настройка, передаётся агенту постановки whitebox через промпт запуска; действует для нарядов, запущенных после сохранения.",
"本组尚未白模调度，当前没有可审看的白模。": "Для этой группы ещё не выполнена постановка whitebox; whitebox для просмотра пока нет.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "Официальный whitebox появится здесь, когда агент постановки whitebox завершит наряд по этой серии; до этого отправлять правки по whitebox не нужно.",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "Грубый whitebox, автоматически выведенный системой из раскадровки и мизансцены; положения камеры, перемещения и направления в основном оценочные и не являются результатом постановки whitebox",
"查看自动推断草稿（仅供参考，不接受修改）": "Посмотреть автоматически выведенный черновик (только для справки, правки не принимаются)",
