"本组尚未白模调度,当前是系统自动推断的草稿,只能查看;白模调度完成后再提修改": "Для этой группы ещё не выполнена постановка whitebox; показан автоматически выведенный черновик, только для просмотра. Правки отправляйте после завершения постановки whitebox",
