"✅ 已提交 {f},手绘原图已直接加入本组参考图,请回桌面端查看": "✅ {f} отправлен; исходный рисунок добавлен в референсы этой группы — посмотрите на компьютере",
"手机扫码手绘构图线稿;勾选「AI 加工」(默认)结合已有参考图按项目风格生成最终参考图,不勾选则手绘原图直接加入本组": "Отсканируйте телефоном и нарисуйте композиционный набросок; с галочкой «Обработка ИИ» (по умолчанию) из наброска, имеющихся референсов и стиля проекта создаётся итоговый референс; без галочки исходный рисунок сразу добавляется в группу",
"手机扫码打开画布(同一局域网);画构图线稿并配文字说明,提交后结合本组已有参考图与项目风格生成最终参考图,自动加入本组;画布页取消勾选「AI 加工」则手绘原图直接加入本组": "Отсканируйте QR-код телефоном, чтобы открыть холст (та же локальная сеть); нарисуйте композиционный набросок и добавьте описание — после отправки из наброска, имеющихся референсов группы и стиля проекта создаётся итоговый референс и автоматически добавляется в группу; снимите галочку «Обработка ИИ» на странице холста, чтобы добавить исходный рисунок напрямую",
"✅ 手绘原图已加入本组参考图": "✅ Исходный рисунок добавлен в референсы этой группы",
"手机扫码打开画布(同一局域网);画好提交后由 AI 按分镜草图风格重绘作为该分镜的草图;画布页取消勾选「AI 加工」则手绘原图直接作为草图": "Отсканируйте QR-код телефоном (та же локальная сеть), чтобы открыть холст; после отправки ИИ перерисует рисунок в стиле эскизов раскадровки как эскиз этого кадра; снимите галочку «Обработка ИИ» на странице холста, чтобы использовать исходный рисунок",
"手机扫码画一张草图;默认由 AI 按分镜草图风格重绘,画布页取消勾选「AI 加工」则原图直接作为这一镜的草图": "Отсканируйте телефоном и нарисуйте эскиз; по умолчанию ИИ перерисует его в стиле эскизов раскадровки — снимите галочку «Обработка ИИ» на странице холста, чтобы использовать оригинал как эскиз этого кадра",
"手绘稿 AI 加工": "Рисунок от руки, обработанный ИИ",
"✅ 已收到手绘稿,AI 正在按分镜草图风格重绘…": "✅ Рисунок получен; ИИ перерисовывает его в стиле эскизов раскадровки…",
"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync (на Fal; липсинк: 1 изображение персонажа + 1 аудио 5–14,8 с, без промпта, длительность по аудио, 480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync: каждый клип использует референс №1 как изображение персонажа (без дрейфа, но со скачками между клипами); формат по изображению",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync: в 1-м раунде референс №1 служит изображением персонажа, далее — последний кадр предыдущего клипа (в режиме «Без связки» всегда референс №1); формат по изображению",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "Модели липсинка нужен хотя бы 1 референс (№1 — изображение персонажа)",
"💬 台词": "💬 Реплики",
"人物要说的话;按句分段,逐段语音合成后驱动口型": "Что говорит персонаж; делится по предложениям, каждый фрагмент синтезируется в речь и затем управляет губами",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "напр.: Всем привет, добро пожаловать на мой стрим! Сегодня хочу рассказать о книге, которую сейчас читаю.",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "Речь синтезируется с текущими настройками TTS и голосом по умолчанию со страницы «Модели генерации» ({tts}). Когда текст закончится, трансляция не останавливается, а ждёт обновления: дописанное в конец произносится следом, переписанный текст читается с начала.",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "Липсинк: текст по предложениям собирается во фрагменты примерно такой длины ({lo}–{hi} с); длительность клипа = длительность речи (короче 5 с дополняется тишиной)",
"✏️ 更新台词": "✏️ Обновить реплики",
"台词已更新": "Реплики обновлены",
"对口型模型需要填写台词(人物要说的话)": "Модели липсинка нужны реплики (что говорит персонаж)",
"点击打开 360° 预览": "Нажмите, чтобы открыть просмотр 360°",
