// 背景图模式(2026-09-22):输出设置「背景图模式」+ 场景预览页分镜背景图板块按场景选择(全景图 / 世界模型)
"背景图模式": "Режим фоновых планшетов",
"白模开启时分镜背景图的参考来源(全局设置,场景预览页可按场景覆盖):全景图=按白模机位自动规划锚点出全景,按镜头方位重投影后二次生成;世界模型=由你在场景预览页选锚点创建全景图、基于它生成世界模型(World Labs Marble,计费),再在世界模型里按镜头方位截图二次生成;九宫格=不出全景,每个场景按布局包里的九个机位、以俯视图为参考一次生成一张 3×3 宫格,拆成 9 张背景图入库,每镜按白模机位自动选最合适的一格": "Источник референсов для фонов кадров при включённом вайтбоксе (глобальная настройка; можно переопределить для сцены на странице предпросмотра сцен): Панорама = якоря планируются автоматически по позициям камер вайтбокса, панорамы перепроецируются по направлению кадра и перегенерируются; Модель мира = вы выбираете якорь на странице предпросмотра сцен, создаёте панораму, по ней строится модель мира (World Labs Marble, платно), затем скриншоты из модели мира по направлению кадра перегенерируются; Сетка 3×3 = без панорамы: каждая сцена одним вызовом генерирует сетку 3×3 по девяти позициям камер из её пакета планировки с планом сверху в качестве референса; сетка режется на 9 фонов, и каждый кадр автоматически выбирает ячейку, ближайшую к его камере вайтбокса",
"本场景分镜背景图的参考来源;默认跟随项目输出设置「背景图模式」,可单独覆盖": "Источник референсов фонов этой сцены; по умолчанию следует настройке вывода проекта «Режим фоновых планшетов», можно переопределить здесь",
"跟随全局({m})": "Как глобально ({m})",
"本场景背景图模式为「世界模型」,但尚未生成世界模型:出图链会停下(退出码 4),请先在上方「🌍 世界模型」板块生成": "Режим фонов этой сцены — «Модель мира», но модель мира ещё не создана: цепочка фонов остановится (код выхода 4). Сначала создайте её в панели «🌍 Модель мира» выше",
