"FastH3 本地 ComfyUI:仅文字生成音视频(T2VA),不支持参考图/首尾帧;参考图必须清空,连续性通过提示词表达": "FastH3 локальный ComfyUI: только генерация видео со звуком из текста (T2VA); референсные изображения и первый/последний кадр не поддерживаются. Референсы нужно очистить, а непрерывность выражать промптом",
