"选中剧本文字可标记「关键情节」或「关键细节」。关键点必须在分镜中体现；取消需确认。": "Выделите текст сценария, чтобы отметить его как «Ключевой сюжетный момент» или «Ключевую деталь». Ключевые моменты обязаны быть отражены в раскадровке; снятие отметки требует подтверждения.",
