"从本场景的背景图库里另选一张,替换这张分镜背景图(改集索引并同步本组 prompt 参考图)": "Выбрать другое изображение из библиотеки фонов этой сцены и заменить фон кадра (перезаписывает индекс серии и синхронизирует референсы промпта группы)",
"手动换图": "заменено вручную",
"🔁 换分镜背景图 —": "🔁 Заменить фон кадра —",
"从本场景的背景图库里点选一张(双击看大图),确认后替换本镜这张背景图:改写集索引 directing/<ep>/shot_plates.json 并同步本组 prompt 的参考图;随本组重出生效,非强制重出不会被自动改回": "Выберите изображение из библиотеки фонов этой сцены (двойной клик — увеличить); после подтверждения оно заменит фон этого кадра: индекс directing/<ep>/shot_plates.json перезаписывается, референсы промпта группы синхронизируются. Вступает в силу при перегенерации группы; непринудительная перегенерация не откатит выбор",
