// 生成模型设置·超分板块 + 成片发布页组 clip 方法标签(2026-09-23,models.html / preview_videos.html)
"图像 / 视频 / 数字人 / 超分 / 音乐 / TTS旁白 / 世界模型 生成渠道与模型": "Провайдеры и модели: изображение / видео / цифровой человек / апскейл / музыка / TTS-озвучка / модель мира",
"🔍 超分": "🔍 Апскейл",
"生效渠道=当前选中的标签页(✅),不再跟随视频渠道,保存后生效": "Активный провайдер = выбранная вкладка (✅), больше не зависит от видеопровайдера; действует после сохранения",
"缩放算法": "Фильтр масштабирования",
"lanczos(默认,较锐利)": "lanczos (по умолчанию, резче)",
"bicubic(平滑)": "bicubic (мягче)",
"bilinear(最软)": "bilinear (самый мягкий)",
"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51; меньше = выше качество и больше размер; 18 ≈ визуально без потерь",
"编码预设": "Пресет кодера",
"slow(默认)": "slow (по умолчанию)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "Встроенная интерполяция без ИИ: фильтр ffmpeg scale + перекодирование libx264, аудио копируется, fps/длительность/соотношение сторон не меняются. Новых деталей нет, только больше пикселей; без затрат на генерацию, подходит проектам, которым нужно лишь пройти спецификацию публикации. Целевой размер берётся из финального разрешения × соотношения сторон в настройках вывода.",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Режим Draft Seedance 2.5: включается выбором этой вкладки; отдельный ключ или модель не нужны, учётные данные и модель берутся из вкладки Volcano Engine генерации видео.",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "Условия: активный видеопровайдер — Volcano Engine (или BytePlus, тот же Ark API) с моделью Seedance 2.5, а в настройках вывода проекта черновик 480p и финал 1080p (официально: черновики только 480p, финалы только 1080p). Иначе видео генерируется обычно, о чём сообщает журнал.",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "Как это работает: ① генерация отправляется с draft=true и даёт черновик 480p (расход токенов как у обычного 480p); id draft-задачи записывается в блок draft_task в meta.json клипа; ② при апскейле genmedia.py upscale просит Ark отрендерить финал 1080p по этому id, повторно используя тот же промпт/материалы/длительность/соотношение/seed/аудио (обычная тарификация), поэтому ключевые элементы совпадают с утверждённым черновиком; ③ id действителен 7 дней с момента создания, затем черновик нужно перегенерировать.",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "Условия (исходный клип должен быть нативным выводом MiniMax-H3 768P): есть аудиодорожка; 24 fps; ширина и высота кратны 32; площадь ≤ 768×1344; 107–362 кадра (около 4–15 с).",
"云端超分工作流": "Облачный workflow апскейла",
"超分工作流 API": "API workflow апскейла",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "(нужна подписка Comfy Cloud, месячный лимит общий с веб-версией; бесплатный тариф без доступа к API); список workflow такой же, как локально (шаблоны comfy/scale-*; узлы SeedVR2 встроены в официальный ComfyUI и доступны в облаке); длинные клипы от 1080p могут не уместиться в видеопамять облака, ориентируйтесь на результат задачи",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "; сначала запустите workflow апскейла класса SeedVR2 в рабочей области, затем вставьте его ID или URL страницы в «Добавить workflow» для проверки; для обычного экспорта без плейсхолдеров система привяжет единственный узел загрузки исходного видео (семейство LoadVideo) + узел изменения размера перед SeedVR2Preprocess (целевая сторона / ширина и высота) + seed сэмплера; плейсхолдеры VIDEO/WIDTH/HEIGHT/SEED тоже поддерживаются; избранное здесь не зависит от карточки генерации видео; аккаунты и ключи .cn и .ai не взаимозаменяемы",
"🧩 组 clip 与超分方法": "🧩 Групповые клипы и метод апскейла",
