"切黑须停留 >0 秒(否则等于停在末帧)": "Резкий уход в чёрное требует удержания > 0 с (иначе просто остановка на последнем кадре)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "Как заканчивается серия: последняя группа затухает в чёрное/белое и удерживается, либо резко обрывается в чёрное (внезапное затемнение для саспенса; звук по умолчанию обрывается в тот же миг); внешняя звуковая дорожка затухает/обрывается в тот же момент, титры идут после удержания. Применяется render_transitions при финальном рендере; для отдельной серии это можно переопределить в сводной строке переходов на странице раскадровки.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "Как заканчивается серия: последняя группа затухает/обрывается в чёрное и удерживается; внешний звук затухает или обрывается в тот же момент; титры идут после удержания",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "Завершение этой серии (переопределение на уровне серии; значение проекта — в «Ритме видео»); применяется при финальном рендере, для готового монтажа нужно заново прогнать переходы",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "Отрендерить превью завершения: последние 2 с последней группы + завершение, та же цепочка фильтров, что и у финального монтажа",
